llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "In normal subjects, the (+)-isomer of verapamil had a mean absolute oral bioavailability of 50% after oral administration, above the 20% threshold; the high transfer score and shared dimethoxyphenyl/tertiary amine features support relevance to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine in healthy volunteers had an absolute oral bioavailability of 30%, above the 20% threshold; its dimethoxybenzene and tetrahydroisoquinoline-like framework with a basic amine is structurally relevant to the query, with a high transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Valbenazine in humans had an absolute oral bioavailability of approximately 49%, above the threshold; it shares a dimethoxy-substituted fused bicyclic amine core with the query and has a high transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Colchicine in elderly subjects had a mean absolute bioavailability of 45% (tablet, 1 mg), above the threshold; despite lacking a basic amine, its P-gp-sensitive absorption and dimethoxy/tropolone aromatic character support a high-F pattern, with a high transfer score.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple high-transfer analogues (verapamil, noscapine, valbenazine, colchicine) show absolute oral bioavailability of 30-55%, all above the 20% threshold, despite basic amine and moderate lipophilicity. Low-F evidence is limited to rifampin-treated verapamil and terameprocol with low transfer or condition mismatch, so it does not outweigh the supportive pattern.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The query's specific enantiomer and its metabolic stability are unknown.",
    "The effect of the lactam/tetralin core on first-pass metabolism is not directly covered by the analogues.",
    "The low neutral fraction (0.02) due to basic pKa 9.05 is a potential absorption liability not directly tested in the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

